namespace sv_1362c037bd2449709a70c7a4fea4d441.Components.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit (per user connection).
/// Holds theme state and notifies subscribers on change.
/// </summary>
public sealed class ThemeService
{
    public ThemeMode Mode { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetMode(ThemeMode mode)
    {
        if (Mode == mode) return;
        Mode = mode;
        OnChange?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChange?.Invoke();
    }

    public void SetTheme(ThemeMode mode, string accentColor)
    {
        var changed = Mode != mode || AccentColor != accentColor;
        Mode = mode;
        AccentColor = accentColor;
        if (changed) OnChange?.Invoke();
    }
}

// Applies theme to the DOM so static-rendered elements react to theme changes.
window.themeInterop = {
    apply: function (mode, accentColor) {
        document.documentElement.setAttribute('data-bs-theme', mode === 'System' ? '' : mode.toLowerCase());
        document.documentElement.style.setProperty('--app-accent-color', accentColor);

        // Update any static header indicator
        const indicator = document.getElementById('theme-indicator');
        if (indicator) {
            indicator.textContent = mode;
            indicator.style.color = accentColor;
        }
    },

    load: function () {
        const json = localStorage.getItem('app-theme');
        return json ? JSON.parse(json) : null;
    },

    save: function (mode, accentColor) {
        localStorage.setItem('app-theme', JSON.stringify({ mode, accentColor }));
    }
};

@* 
    Place this component inside the layout with @rendermode InteractiveServer.
    It bridges the scoped ThemeService to the DOM so that static elements
    (header indicator, html data-bs-theme attribute) stay in sync.
*@
@rendermode InteractiveServer
@inject ThemeService Theme
@inject IJSRuntime JS
@implements IDisposable

@code {
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Restore persisted theme from localStorage
            var saved = await JS.InvokeAsync<ThemeState?>("themeInterop.load");
            if (saved is not null)
            {
                var mode = Enum.TryParse<ThemeMode>(saved.Mode, out var m) ? m : ThemeMode.System;
                Theme.SetTheme(mode, saved.AccentColor ?? "#0d6efd");
            }

            await ApplyToDOM();
        }
    }

    protected override void OnInitialized()
    {
        Theme.OnChange += HandleThemeChanged;
    }

    private async void HandleThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            await ApplyToDOM();
            StateHasChanged();
        });
    }

    private async Task ApplyToDOM()
    {
        var modeName = Theme.Mode.ToString();
        await JS.InvokeVoidAsync("themeInterop.apply", modeName, Theme.AccentColor);
        await JS.InvokeVoidAsync("themeInterop.save", modeName, Theme.AccentColor);
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleThemeChanged;
    }

    private record ThemeState(string? Mode, string? AccentColor);
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService Theme
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme Mode</label>
    <select class="form-select" @bind="selectedMode">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color" @bind="accentColor" />
</div>

<button class="btn btn-primary" @onclick="Save">Save Preferences</button>

<p class="mt-3">
    Current: <strong>@Theme.Mode</strong> / <span style="color: @Theme.AccentColor">@Theme.AccentColor</span>
</p>

@code {
    private ThemeMode selectedMode;
    private string accentColor = "#0d6efd";

    protected override void OnInitialized()
    {
        selectedMode = Theme.Mode;
        accentColor = Theme.AccentColor;
        Theme.OnChange += HandleChanged;
    }

    private void Save()
    {
        Theme.SetTheme(selectedMode, accentColor);
    }

    private async void HandleChanged()
    {
        await InvokeAsync(() =>
        {
            selectedMode = Theme.Mode;
            accentColor = Theme.AccentColor;
            StateHasChanged();
        });
    }

    public void Dispose()
    {
        Theme.OnChange -= HandleChanged;
    }
}

