// Applies theme to the DOM so static-rendered elements react to theme changes.
window.themeInterop = {
    apply: function (mode, accentColor) {
        document.documentElement.setAttribute('data-bs-theme', mode === 'System' ? '' : mode.toLowerCase());
        document.documentElement.style.setProperty('--app-accent-color', accentColor);

        // Update any static header indicator
        const indicator = document.getElementById('theme-indicator');
        if (indicator) {
            indicator.textContent = mode;
            indicator.style.color = accentColor;
        }
    },

    load: function () {
        const json = localStorage.getItem('app-theme');
        return json ? JSON.parse(json) : null;
    },

    save: function (mode, accentColor) {
        localStorage.setItem('app-theme', JSON.stringify({ mode, accentColor }));
    }
};

